#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — DocuLens free hosting: GitHub, Groq, Supabase, Google sign-in,
# Render (API), Vercel (website). Values land in .env.deploy (git-ignored).
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10
cd "$(dirname "$0")/.."
ENV_FILE=".env.deploy"
PY=".venv/bin/python"
[[ -x "$PY" ]] || { printf 'Create the Python environment first: python3 -m venv .venv && .venv/bin/pip install -r backend/requirements.txt\n'; exit 1; }

banner "DocuLens: free hosting setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "GitHub: sign in and publish the code"
say "The code goes to a public GitHub repository. Vercel deploys the website from it,"
say "and GitHub Actions deploys the API and keeps the free services awake."
if ! gh auth status >/dev/null 2>&1; then
  step "A browser window will ask you to sign in to GitHub as agr-arsh-15."
  gh auth login --hostname github.com --git-protocol https --web
fi
ask GITHUB_REPO_NAME "Repository name (e.g. doculens):"
GITHUB_REPO_NAME="${GITHUB_REPO_NAME:-doculens}"
write_env GITHUB_REPO_NAME "$GITHUB_REPO_NAME"
if git remote get-url origin >/dev/null 2>&1; then
  note "A remote called origin already exists: $(git remote get-url origin)"
  git push -u origin main
else
  confirm "Create the PUBLIC repository $GITHUB_REPO_NAME and push the code?" && \
    gh repo create "$GITHUB_REPO_NAME" --public --source . --remote origin --push \
      --description "DocuLens: contract and terms risk analyzer with sourced market standards"
fi
GITHUB_REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner)
note "Repository: https://github.com/$GITHUB_REPO"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Groq: rotate the API key"
warn "The old Groq key was pasted into a chat earlier, so treat it as exposed."
open_url "https://console.groq.com/keys"
step "Delete the old key (trash icon on its row)."
step "Click 'Create API Key', name it 'doculens-hosted', and copy it (starts gsk_)."
ask_secret GROQ_API_KEY "Paste the NEW Groq key:"
write_env GROQ_API_KEY "$GROQ_API_KEY"
ENV_FILE=".env" write_env GROQ_API_KEY "$GROQ_API_KEY"
note "Also updated your local .env so the laptop version uses the new key."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Choose the public address and the admin"
say "Vercel gives the website a free address: https://<project-name>.vercel.app"
ask VERCEL_PROJECT "Vercel project name (lowercase letters, digits and dashes, e.g. doculens):"
VERCEL_PROJECT=$(printf '%s' "$VERCEL_PROJECT" | tr '[:upper:]' '[:lower:]' | tr -c 'a-z0-9-\n' '-')
SITE_URL="https://${VERCEL_PROJECT}.vercel.app"
write_env VERCEL_PROJECT "$VERCEL_PROJECT"
write_env SITE_URL "$SITE_URL"
note "Website address: $SITE_URL (the API's address comes from Render in stage 7)."
ask ADMIN_EMAILS "Google account(s) that get the admin dashboard [agrawalarsh15@gmail.com]:"
ADMIN_EMAILS="${ADMIN_EMAILS:-agrawalarsh15@gmail.com}"
write_env ADMIN_EMAILS "$ADMIN_EMAILS"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase: create the project"
open_url "https://supabase.com/dashboard/new"
step "Sign in (GitHub works), create an organisation if asked (Free plan)."
step "New project: name 'doculens', a strong database password, region close to your users (e.g. Mumbai)."
step "Save the database password somewhere safe, then wait about 2 minutes until the project is ready."
pause "Press Enter when the project dashboard has loaded"
step "Open Project Settings -> Data API (or the project's Connect dialog) and copy the Project URL."
ask SUPABASE_URL "Project URL (https://<ref>.supabase.co):"
SUPABASE_URL="${SUPABASE_URL%/}"
SUPABASE_URL="${SUPABASE_URL%/rest/v1}"
SUPABASE_URL="${SUPABASE_URL%/auth/v1}"
note "Using $SUPABASE_URL"
write_env SUPABASE_URL "$SUPABASE_URL"
step "Open Project Settings -> API Keys. Copy the Publishable key (sb_publishable_...)."
ask SUPABASE_PUBLISHABLE_KEY "Publishable key:"
write_env SUPABASE_PUBLISHABLE_KEY "$SUPABASE_PUBLISHABLE_KEY"
step "On the same page, under Secret keys, reveal and copy the default secret key (sb_secret_...)."
ask_secret SUPABASE_SERVICE_ROLE_KEY "Secret key (hidden):"
write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Supabase: database connection and private file storage"
DATABASE_URL=$(_existing DATABASE_URL || true)
if [[ -z "$DATABASE_URL" ]] || ! confirm "Keep the database connection saved in an earlier run?"; then
  step "Click 'Connect' at the top of the dashboard -> Connection String -> choose 'Session pooler'."
  step "Copy the URI (postgresql://postgres.<ref>:[YOUR-PASSWORD]@aws-...pooler.supabase.com:5432/postgres)."
  ask_secret DB_URI "Paste the URI (hidden):"
  ask_secret DB_PASSWORD "Database password you chose in stage 4 (hidden):"
  DB_PASSWORD_ENC=$("$PY" -c 'import sys,urllib.parse; print(urllib.parse.quote(sys.argv[1], safe=""))' "$DB_PASSWORD")
  DATABASE_URL="${DB_URI/\[YOUR-PASSWORD\]/$DB_PASSWORD_ENC}"
  DATABASE_URL="${DATABASE_URL/postgresql:\/\//postgresql+psycopg://}"
  DATABASE_URL="${DATABASE_URL/postgres:\/\//postgresql+psycopg://}"
fi
write_env DATABASE_URL "$DATABASE_URL"
say "Creating the private 'documents' bucket for original uploads..."
if [[ "$SUPABASE_SERVICE_ROLE_KEY" == sb_* ]]; then AUTH_HDR=(); else AUTH_HDR=(-H "Authorization: Bearer $SUPABASE_SERVICE_ROLE_KEY"); fi
code=$(curl -s -o /tmp/doculens-bucket.json -w '%{http_code}' -X POST "$SUPABASE_URL/storage/v1/bucket" \
  -H "apikey: $SUPABASE_SERVICE_ROLE_KEY" ${AUTH_HDR[@]+"${AUTH_HDR[@]}"} -H "Content-Type: application/json" \
  -d '{"id":"documents","name":"documents","public":false,"file_size_limit":15728640}')
if [[ "$code" == 200 || "$code" == 201 ]] || grep -qi "already exists" /tmp/doculens-bucket.json; then
  printf '  %s✓%s bucket "documents" is ready (private)\n' "$GREEN" "$RESET"
else
  warn "Could not create the bucket automatically (HTTP $code). In the dashboard: Storage -> New bucket -> name 'documents', Public OFF."
  pause "Press Enter once the bucket exists"
fi
write_env SUPABASE_STORAGE_BUCKET "documents"
say "Checking the database connection and creating the tables..."
if DATABASE_URL="$DATABASE_URL" "$PY" -c "import sys; sys.path.insert(0,'backend'); from app.storage import db; db.init_db(); print('  tables ready')"; then
  :
else
  warn "The database connection failed. Re-run the wizard and check the URI and password."
  exit 1
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Google sign-in (Google Cloud + Supabase)"
open_url "https://console.cloud.google.com/auth/overview"
step "Create a project named 'DocuLens' if asked, then click 'Get started' (Google Auth Platform)."
step "App name: DocuLens. Support e-mail: your Gmail. Audience: External. Contact e-mail: your Gmail. Create."
step "Branding: Home page $SITE_URL, Privacy policy $SITE_URL/privacy, Terms $SITE_URL/terms."
step "Audience: click 'Publish app' so anyone with a Google account can sign in."
step "Clients -> Create client -> Web application, name 'DocuLens web':"
note "    Authorized JavaScript origins:  $SITE_URL   and   http://localhost:5173"
note "    Authorized redirect URIs:       $SUPABASE_URL/auth/v1/callback"
step "Create, then copy the Client ID and Client secret (you paste them into Supabase next)."
pause "Press Enter when you have both values"
SUPABASE_REF="${SUPABASE_URL#https://}"
SUPABASE_REF="${SUPABASE_REF%%.*}"
open_url "https://supabase.com/dashboard/project/${SUPABASE_REF}/auth/providers"
step "In Supabase: Authentication -> Sign In / Providers -> Google -> enable, paste Client ID and secret, Save."
step "Authentication -> URL Configuration:"
note "    Site URL:       $SITE_URL"
note "    Redirect URLs:  $SITE_URL/auth/callback   and   http://localhost:5173/auth/callback"
pause "Press Enter when Google is enabled and the URLs are saved"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Render: create the API service"
say "Render runs the API for free (512 MB RAM; it sleeps after 15 minutes idle and wakes in about a minute)."
open_url "https://render.com/deploy?repo=https://github.com/$GITHUB_REPO"
step "Sign in with GitHub and allow Render to read the $GITHUB_REPO repository if asked."
step "Render reads render.yaml: name the Blueprint 'doculens', keep the free 'doculens-api' web service, click 'Deploy Blueprint'."
note "The first start fails until the secrets are set in a moment; that is expected."
pause "Press Enter once the doculens-api service appears in your Render dashboard"
open_url "https://dashboard.render.com/u/settings#api-keys"
step "Account Settings -> API Keys -> Create API Key, name it 'doculens-setup', copy it (starts rnd_)."
ask_secret RENDER_API_KEY "Paste the Render API key (hidden):"
write_env RENDER_API_KEY "$RENDER_API_KEY"
ENCRYPTION_KEY=$(_existing ENCRYPTION_KEY || true)
if [[ -z "$ENCRYPTION_KEY" ]]; then
  ENCRYPTION_KEY=$("$PY" -c "from cryptography.fernet import Fernet; print(Fernet.generate_key().decode())")
  note "Generated a new encryption key for users' saved Groq keys."
fi
write_env ENCRYPTION_KEY "$ENCRYPTION_KEY"
write_env CORS_ORIGINS "$SITE_URL"
if confirm "Set the API's secrets on Render and deploy it?"; then
  OUT=$(RENDER_API_KEY="$RENDER_API_KEY" ENV_FILE="$ENV_FILE" "$PY" scripts/render_deploy.py)
  printf '%s\n' "$OUT" | grep -v '^API_URL=' | sed 's/^/  /'
  API_URL=$(printf '%s\n' "$OUT" | sed -n 's/^API_URL=//p')
  write_env API_URL "$API_URL"
fi
note "Building takes about 5 minutes. Watch it in the Render dashboard under doculens-api -> Events."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "GitHub Actions: keep-alive"
API_URL=$(_existing API_URL || true)
set_var API_URL "$API_URL"
say "Render redeploys the API by itself after every push to main once the tests pass."
say "A GitHub Actions job pings $API_URL every 10 minutes so the API and the database stay awake."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Vercel: deploy the website"
open_url "https://vercel.com/new"
step "Sign in with GitHub, then Import the repository $GITHUB_REPO."
step "Project Name: $VERCEL_PROJECT. Leave Root Directory as ./ (vercel.json does the rest)."
step "Open 'Environment Variables' and add these three, then click Deploy:"
note "    VITE_API_URL                   = $API_URL"
note "    VITE_SUPABASE_URL              = $SUPABASE_URL"
note "    VITE_SUPABASE_PUBLISHABLE_KEY  = $SUPABASE_PUBLISHABLE_KEY"
pause "Press Enter when the deployment shows 'Ready'"
ask DEPLOYED_URL "The site address Vercel shows [$SITE_URL]:"
DEPLOYED_URL="${DEPLOYED_URL:-$SITE_URL}"
DEPLOYED_URL="${DEPLOYED_URL%/}"
if [[ "$DEPLOYED_URL" != "$SITE_URL" ]]; then
  warn "The address differs from $SITE_URL. Updating the API's allowed origin..."
  SITE_URL="$DEPLOYED_URL"
  write_env SITE_URL "$SITE_URL"
  write_env CORS_ORIGINS "$SITE_URL"
  RENDER_API_KEY="$RENDER_API_KEY" "$PY" scripts/render_deploy.py "CORS_ORIGINS=$SITE_URL" | grep -v '^API_URL=' | sed 's/^/  /'
  warn "Also replace the old address in Google (JavaScript origin) and Supabase (Site URL and Redirect URL) with $SITE_URL."
  pause
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Check that everything is live"
say "Waiting for the API to answer (the first build can take a few minutes)..."
for i in $(seq 1 40); do
  if curl -fsS --max-time 60 "$API_URL/api/health?deep=1" >/dev/null 2>&1; then
    printf '  %s✓%s API and database are up: %s\n' "$GREEN" "$RESET" "$API_URL"
    break
  fi
  [[ $i == 40 ]] && warn "The API is not answering yet. Check the logs in the Render dashboard (doculens-api -> Logs)."
  sleep 15
done
open_url "$SITE_URL"
step "Sign in with Google using $ADMIN_EMAILS, upload a document, and open Admin dashboard from the avatar menu."
pause "Press Enter to finish"

finish
